import math

class AlphaGoMCTSNode:
    def __init__(self, prior_p=0.0):
        self.prior_p = prior_p
        self.visit_count = 0
        self.total_value = 0.0
        self.children = {}

    @property
    def q_value(self):
        return self.total_value / self.visit_count if self.visit_count > 0 else 0.0

def puct_select(node, c_puct=1.5):
    total_visits = sum(child.visit_count for child in node.children.values())
    sqrt_total = math.sqrt(total_visits)
    return max(node.children.items(), key=lambda item: item[1].q_value + c_puct * item[1].prior_p * sqrt_total / (1 + item[1].visit_count))[0]

# Source: open_spiel/algorithms/alpha_zero/alpha_zero.py
import torch

def select_move_with_temperature(visit_counts, temperature=1.0):
    visits = torch.tensor(visit_counts, dtype=torch.float32)
    if temperature == 0.0:
        return torch.argmax(visits).item()
    probs = (visits ** (1.0 / temperature))
    probs = probs / probs.sum()
    return torch.multinomial(probs, 1).item()

