import torch
import torch.nn as nn

class MuZeroNet(nn.Module):
    def __init__(self, obs_dim=128, latent_dim=64, action_dim=4):
        super().__init__()
        self.representation = nn.Sequential(nn.Linear(obs_dim, latent_dim), nn.ReLU())
        self.dynamics = nn.Sequential(nn.Linear(latent_dim + action_dim, latent_dim), nn.ReLU())
        self.reward_head = nn.Linear(latent_dim, 1)
        self.prediction_policy = nn.Linear(latent_dim, action_dim)
        self.prediction_value = nn.Linear(latent_dim, 1)

    def initial_inference(self, obs):
        s0 = self.representation(obs)
        return s0, self.prediction_policy(s0), self.prediction_value(s0)

    def recurrent_inference(self, s_prev, action_onehot):
        x = torch.cat([s_prev, action_onehot], dim=-1)
        s_next = self.dynamics(x)
        r = self.reward_head(s_next)
        return s_next, r, self.prediction_policy(s_next), self.prediction_value(s_next)

