import torch
import torch.nn as nn

class GatoTransformer(nn.Module):
    def __init__(self, vocab_size=32000, d_model=1536, layers=24):
        super().__init__()
        self.embed = nn.Embedding(vocab_size, d_model)
        self.transformer = nn.TransformerEncoder(
            nn.TransformerEncoderLayer(d_model, nhead=16, dim_feedforward=6144, batch_first=True),
            num_layers=layers
        )
        self.head = nn.Linear(d_model, vocab_size)

    def forward(self, unified_tokens, causal_mask):
        x = self.embed(unified_tokens)
        h = self.transformer(x, mask=causal_mask)
        return self.head(h)

