# Source: open_x_embodiment/models/rt2_vla.py (Brohan et al. 2023)
class ActionTokenizer:
    def __init__(self, bins=256, min_val=-1.0, max_val=1.0):
        self.bins = bins
        self.min_val, self.max_val = min_val, max_val

    def continuous_to_tokens(self, action_vector_7d):
        normalized = (action_vector_7d - self.min_val) / (self.max_val - self.min_val)
        token_ids = (normalized * (self.bins - 1)).clip(0, self.bins - 1).astype(int)
        return token_ids

# Source: robocat/agent.py (Bousmalis et al. 2023)
class RoboCatSelfImprovementLoop:
    def __init__(self, foundation_agent, robot_env):
        self.agent = foundation_agent
        self.env = robot_env
        self.buffer = []

    def cycle(self, num_trials=500):
        # 1. Autonomous execution and filtering
        for _ in range(num_trials):
            traj, success = self.env.rollout(self.agent)
            if success:
                self.buffer.append(traj)
        # 2. Retrain and self-improve
        self.agent.fine_tune(self.buffer)

