class OverthinkingDetector:
    def should_halt(self, attention_entropy_history, epsilon=1e-4):
        if len(attention_entropy_history) < 5:
            return False
        rate_of_change = abs(attention_entropy_history[-1] - attention_entropy_history[-5])
        return rate_of_change < epsilon

